                using var call = global::Pbwire.ImageCall.Rent(ImageBytes, wire.Length * 6 + 65536);
                Plan.Decode(wire, call.Image, call.DecodeArena, call.DecodeArenaBytes);
                var native = new AddressBook();
                native.ReadImage(call.Image);
                return native;
            }
        }

    }

}
